 WHERE car04_company_id = #{companyId}
   AND car04_journal_id IN
#{id}

mapper.select:
SELECT COALESCE(car04_journal_id, ROW_NUMBER() OVER()) AS journal_id , COALESCE(car04_company_id, car01_company_id) AS company_id , COALESCE(car04_info_id, car01_info_id) AS info_id , COALESCE(car04_date, car03_start_date) AS "date" , COALESCE(car04_person_id, car03_person_id) AS person_id , COALESCE(car04_mileage, 0) AS mileage , CAST(NULL AS numeric) AS before_mileage , CAST(NULL AS numeric) AS after_mileage , COALESCE(car04_commute_mileage, 0) AS commute_mileage , COALESCE(car04_biz_mileage, 0) AS biz_mileage , COALESCE(car04_un_biz_mileage, 0) AS un_biz_mileage , COALESCE(car04_destination, car03_destination) AS destination , COALESCE(car04_reason, car03_reason) AS reason , COALESCE(car04_note, car03_note) AS note , COALESCE(car04_booking_id, car03_booking_id) AS booking_id , (COALESCE(car04_fix_yn, 'false') = 'true') AS fix_yn , (COALESCE(car04_close_yn, 'false') = 'true') AS close_yn , COALESCE(car04_commute_mileage, 0) + COALESCE(car04_biz_mileage, 0) AS business_mileage , car01_car_no || ' - ' || car01_car_nm AS info_nm , car03_attendance AS attendance FROM car03_booking INNER JOIN car01_info ON car01_info_id = car03_info_id AND car01_car_type = '2' LEFT OUTER JOIN car04_journal ON car04_booking_id = car03_booking_id WHERE 1=1 AND car01_company_id = #{companyId} AND to_char(car03_start_date, 'YYYY.MM') LIKE #{stdMonth} AND ( COALESCE(car04_person_id, car03_person_id) = #{personId} OR COALESCE(car04_person_id, car03_reg_emp_id) = #{personId} )
AND car01_info_id = #{infoId}
ORDER BY COALESCE(car04_date, car03_start_date), COALESCE(car04_journal_id, ROW_NUMBER() OVER())

SELECT COUNT(*)
  FROM car04_journal
       INNER JOIN car01_info ON car01_info_id = car04_info_id
 WHERE car04_booking_id = #{bookingId}
   AND car04_company_id = #{companyId}

SELECT a.car04_journal_id AS journal_id, a.car04_company_id AS company_id, a.car04_info_id AS info_id, a.car04_date AS "date", a.car04_person_id AS person_id, a.car04_mileage AS mileage, a.car04_commute_mileage AS commute_mileage, a.car04_biz_mileage AS biz_mileage, a.car04_un_biz_mileage AS un_biz_mileage, a.car04_destination AS destination, a.car04_reason AS reason, a.car04_note AS note, a.car04_booking_id AS booking_id, (a.car04_fix_yn = 'true') AS fix_yn, (a.car04_close_yn = 'true') AS close_yn, a.car04_commute_mileage + a.car04_biz_mileage AS business_mileage, a.car04_info_nm AS info_nm, a.car04_attendance AS attendance, a.car04_datetime AS datetime, a.car04_week_nm AS week_name, a.car04_person_nm AS person_nm, a.car04_start_hour AS start_hour, a.car04_start_min AS start_min, a.car04_close_hour AS close_hour, a.car04_close_min AS close_min FROM (
SELECT COALESCE(car04_journal_id, ROW_NUMBER() OVER()) AS car04_journal_id , COALESCE(car04_company_id, car01_company_id) AS car04_company_id , COALESCE(car04_info_id, car01_info_id) AS car04_info_id , COALESCE(car04_date, car03_start_date) AS car04_date , COALESCE(car04_person_id, car03_person_id) AS car04_person_id , COALESCE(car04_mileage, 0) AS car04_mileage , COALESCE(car04_commute_mileage, 0) AS car04_commute_mileage , COALESCE(car04_biz_mileage, 0) AS car04_biz_mileage , COALESCE(car04_un_biz_mileage, 0) AS car04_un_biz_mileage , COALESCE(car04_destination, car03_destination) AS car04_destination , COALESCE(car04_reason, car03_reason) AS car04_reason , COALESCE(car04_note, car03_note) AS car04_note , COALESCE(car04_booking_id, car03_booking_id) AS car04_booking_id , COALESCE(car04_fix_yn, 'false') AS car04_fix_yn , COALESCE(car04_close_yn, 'false') AS car04_close_yn , car01_car_no || ' - ' || car01_car_nm AS car04_info_nm , car03_attendance AS car04_attendance , TO_CHAR(COALESCE(car04_date, car03_start_date),'YYYY-MM-DD') ||' '|| car03_start_hour||':'||car03_start_min ||' ~ '|| car03_close_hour||':'||car03_close_min AS car04_datetime , ( CASE TO_CHAR(COALESCE(car04_date, car03_start_date), 'D') WHEN '1' THEN '<'||'span style=color:#DD5E5E;'||'>'||'일요일'||'<'||'/span'||'>' WHEN '2' THEN '<'||'span style=color:#000000;'||'>'||'월요일'||'<'||'/span'||'>' WHEN '3' THEN '<'||'span style=color:#000000;'||'>'||'화요일'||'<'||'/span'||'>' WHEN '4' THEN '<'||'span style=color:#000000;'||'>'||'수요일'||'<'||'/span'||'>' WHEN '5' THEN '<'||'span style=color:#000000;'||'>'||'목요일'||'<'||'/span'||'>' WHEN '6' THEN '<'||'span style=color:#000000;'||'>'||'금요일'||'<'||'/span'||'>' WHEN '7' THEN '<'||'span style=color:#597EB1;'||'>'||'토요일'||'<'||'/span'||'>' END ) AS car04_week_nm , f_emp_kor_nm(car03_person_id) AS car04_person_nm , car03_start_hour AS car04_start_hour , car03_start_min AS car04_start_min , car03_close_hour AS car04_close_hour , car03_close_min AS car04_close_min , car03_booking.* FROM car03_booking INNER JOIN car01_info ON car01_info_id = car03_info_id AND car01_car_type = '2' LEFT OUTER JOIN car04_journal ON car04_booking_id = car03_booking_id WHERE 1=1 AND car01_company_id = #{companyId} AND to_char(car03_start_date,'YYYY.MM') LIKE #{stdMonth}
AND car01_info_id = #{infoId}
) a WHERE UPPER(CONCAT(a.car04_week_nm, a.car04_person_nm, a.car03_destination, a.car03_reason)) LIKE UPPER(#{searchText}) ORDER BY a.car04_info_nm COLLATE "ko_KR.utf8", a.car04_date, COALESCE(a.car03_start_hour, '00')

SELECT car04_journal_id
  FROM car04_journal
 WHERE car04_booking_id = #{bookingId}
   AND car04_company_id = #{companyId}
 ORDER BY car04_journal_id
 LIMIT 1

