mapper.update:
UPDATE car04_journal
   SET car04_before_mileage = #{beforeMileage},
       car04_after_mileage  = #{afterMileage},
       car04_close_yn       = CASE WHEN #{closeYn} THEN 'true' ELSE 'false' END
 WHERE car04_journal_id = #{journalId}
   AND car04_company_id = #{companyId}

mapper.select:
SELECT car05_appr_id AS appr_id
     , apr01_status_cd AS status_code
     , f_cdnm('AprStatusCode', apr01_status_cd, car05_company_id, apr01_reg_date) AS status_name
  FROM car05_relate_appr
       INNER JOIN apr01_appr ON apr01_appr_id = car05_appr_id
 WHERE car05_info_id = #{infoId}
   AND car05_company_id = #{companyId}
   AND car05_yyyymm LIKE #{stdMonth}

